  if len(a):rows.append((m.get('sim_time_s',0),d,a[0,8:15],a[-1,8:15],m.get('time_left_s')))
for sim,d,first,last,left in sorted(rows)[:20]:print(f'{sim:8.3f} {left:8.1f} {d:30s} first={np.round(first,3)} last={np.round(last,3)}')
